<?php require 'config.php'; role(['admin','manajer']);$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$stmt=$conn->prepare("SELECT t.*,u.name cashier FROM transactions t JOIN users u ON u.id=t.user_id WHERE t.status='paid' AND created_at BETWEEN ? AND ? ORDER BY created_at DESC");$a=$from.' 00:00:00';$b=$to.' 23:59:59';$stmt->bind_param('ss',$a,$b);$stmt->execute();$rows=$stmt->get_result();$agg=$conn->prepare("SELECT COALESCE(SUM(total_amount),0) total, COUNT(*) cnt FROM transactions WHERE status='paid' AND created_at BETWEEN ? AND ?");$agg->bind_param('ss',$a,$b);$agg->execute();$av=$agg->get_result()->fetch_assoc();$total=(int)$av['total'];$count=(int)$av['cnt'];include 'partials/header.php';?><div class="mb-3"><div class="section-title">Laporan Penjualan</div><div class="sub">Filter transaksi berdasarkan periode tanggal.</div></div><div class="cardx p-3"><form class="row g-2 align-items-end"><div class="col-md-4"><label class="sub mb-1">Dari</label><input class="form-control" type="date" name="from" value="<?=$from?>"></div><div class="col-md-4"><label class="sub mb-1">Sampai</label><input class="form-control" type="date" name="to" value="<?=$to?>"></div><div class="col-md-4 d-flex gap-2"><button class="btn btn-primary flex-fill">Tampilkan</button><button type="button" onclick="print()" class="btn btn-light">Cetak</button></div></form></div><div class="row g-3 mt-1"><div class="col-md-6"><div class="cardx p-3"><div class="sub">Total Pendapatan</div><div style="font-size:22px;font-weight:700"><?=rupiah($total)?></div></div></div><div class="col-md-6"><div class="cardx p-3"><div class="sub">Jumlah Transaksi</div><div style="font-size:22px;font-weight:700"><?=$count?></div></div></div></div><div class="cardx mt-3"><div class="card-head"><div><h5>Detail Laporan</h5><small><?=date('d/m/Y',strtotime($from))?> — <?=date('d/m/Y',strtotime($to))?></small></div></div><div class="table-responsive p-2"><table class="table mb-0"><thead><tr><th>INVOICE</th><th>KASIR</th><th>TOTAL</th><th>METODE</th><th>WAKTU</th></tr></thead><tbody><?php while($t=$rows->fetch_assoc()):$total+=(int)$t['total_amount'];$count++;?><tr><td><b><?=$t['invoice_code']?></b></td><td><?=$t['cashier']?></td><td><?=rupiah($t['total_amount'])?></td><td><?=$t['payment_method']?></td><td><?=$t['created_at']?></td></tr><?php endwhile;?><tr><td colspan="2"><b>Total</b></td><td><b><?=rupiah($total)?></b></td><td colspan="2"><b><?=$count?> transaksi</b></td></tr></tbody></table></div></div><?php include 'partials/footer.php';?>